// Aggregate answers with their questions
const qbItems = $('Get Random QuestionBank Items').all();
const answersData = $('Get QuestionBank Answers').all();

// Group answers by questionbank ID
const answersByQB = {};
for (const answerItem of answersData) {
  const qbid = answerItem.json.questionbankid || $json.id;
  if (!answersByQB[qbid]) {
    answersByQB[qbid] = [];
  }
  answersByQB[qbid].push({
    letter: answerItem.json.answer,
    text: answerItem.json.answertext,
    is_correct: answerItem.json.iscorrect === 1
  });
}

// Get first item to determine test grade and subject
const firstItem = qbItems[0].json;
const grade = firstItem.grade || '3';
const subjectarea = firstItem.subjectarea || 2;
const testName = $('Set Parameters').first().json.test_name;

// Build questionbank items with answers
const qbWithAnswers = qbItems.map(qbItem => {
  const qb = qbItem.json;
  return {
    id: qb.id,
    type: qb.type,
    correct: qb.correct,
    points: qb.points || 1.0,
    grade: qb.grade,
    subjectarea: qb.subjectarea,
    html: qb.html,
    answers: answersByQB[qb.id] || []
  };
});

return [{
  json: {
    test_name: testName,
    grade: grade,
    subjectarea: subjectarea,
    questionbank_items: qbWithAnswers
  }
}];

// Get the test ID and questionbank items
const testId = $('Create Test').first().json.test_id;
const qbItems = $('Prepare Test Data').first().json.questionbank_items;

// Return each questionbank item with test_id and question order
return qbItems.map((qb, index) => ({
  json: {
    test_id: testId,
    qorder: index + 1,
    qb_id: qb.id,
    qb_type: qb.type,
    qb_points: qb.points,
    qb_html: qb.html,
    qb_answers: qb.answers
  }
}));

